arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews and book appointments instantly with MedBook." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --blue: #0066ff;
      --blue-dark: #0052cc;
      --navy: #1b1464;
      --teal: #16b39a;
      --teal-dark: #10917d;
      --text: #10213f;
      --muted: #5d6b85;
      --white: #ffffff;
      --surface: #f4f8ff;
      --surface-2: #eef4ff;
      --border: #d7e2ff;
      --shadow: 0 10px 30px rgba(15, 54, 120, 0.12);
      --radius-lg: 20px;
      --radius-md: 14px;
      --radius-sm: 10px;
      --container: min(1120px, calc(100% - 2rem));
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background: var(--white);
      line-height: 1.5;
    }

    .container { width: var(--container); margin-inline: auto; }
    a { color: inherit; text-decoration: none; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 30;
      background: rgba(255, 255, 255, 0.94);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid #edf2ff;
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 74px;
      gap: 1rem;
    }

    .logo {
      font-weight: 800;
      font-size: 1.4rem;
      color: var(--navy);
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .logo-mark {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--blue), #4c92ff);
      position: relative;
      box-shadow: 0 8px 18px rgba(0, 102, 255, 0.28);
    }

    .logo-mark::before,
    .logo-mark::after {
      content: "";
      position: absolute;
      background: white;
      border-radius: 999px;
    }

    .logo-mark::before { width: 18px; height: 4px; inset: 15px 8px auto; }
    .logo-mark::after { width: 4px; height: 18px; inset: 8px auto auto 15px; }

    .nav-links { display: flex; align-items: center; gap: 1.2rem; }
    .nav-links a {
      color: #33456b;
      font-weight: 600;
      padding: 0.3rem 0.45rem;
      border-radius: 8px;
      transition: color .2s ease, background .2s ease;
    }
    .nav-links a:hover { color: var(--blue); background: #f0f5ff; }
    .nav-links .signup {
      background: var(--blue);
      color: white;
      padding: 0.6rem 0.95rem;
      border-radius: 10px;
    }
    .nav-links .signup:hover { background: var(--blue-dark); color: white; }

    .menu-btn {
      display: none;
      border: 1px solid var(--border);
      background: white;
      width: 42px;
      height: 42px;
      border-radius: 12px;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }

    .menu-btn span,
    .menu-btn span::before,
    .menu-btn span::after {
      display: block;
      width: 18px;
      height: 2px;
      border-radius: 999px;
      background: #344060;
      position: relative;
      transition: transform .25s ease;
    }
    .menu-btn span::before,
    .menu-btn span::after { content: ""; position: absolute; left: 0; }
    .menu-btn span::before { top: -6px; }
    .menu-btn span::after { top: 6px; }

    .mobile-drawer {
      position: fixed;
      inset: 74px 0 0 auto;
      width: min(280px, 82vw);
      background: white;
      box-shadow: var(--shadow);
      border-left: 1px solid var(--border);
      transform: translateX(100%);
      transition: transform .28s ease;
      z-index: 40;
      padding: 1rem;
    }
    .mobile-drawer.open { transform: translateX(0); }
    .mobile-drawer a {
      display: block;
      padding: 0.9rem 0.8rem;
      border-radius: 10px;
      font-weight: 600;
      color: #33456b;
    }
    .mobile-drawer a:hover { background: #f2f6ff; color: var(--blue); }

    .hero {
      padding: 4.2rem 0 2.2rem;
      background: radial-gradient(circle at 10% 10%, #edf5ff 0%, #ffffff 60%);
    }

    .hero-content {
      display: grid;
      grid-template-columns: 1.05fr .95fr;
      align-items: center;
      gap: 2rem;
    }

    h1 {
      margin: 0 0 0.85rem;
      font-size: clamp(2rem, 4vw, 3.5rem);
      line-height: 1.08;
      letter-spacing: -0.02em;
      color: #101f47;
    }

    .subtitle {
      font-size: 1.1rem;
      color: var(--muted);
      max-width: 62ch;
      margin: 0 0 1.5rem;
    }

    .hero-actions { display: flex; gap: .8rem; flex-wrap: wrap; }
    .btn {
      border: none;
      border-radius: 12px;
      font-weight: 700;
      padding: 0.85rem 1.2rem;
      cursor: pointer;
      font-size: 1rem;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
    }
    .btn-primary { background: var(--blue); color: white; box-shadow: 0 8px 18px rgba(0,102,255,.26); }
    .btn-primary:hover { background: var(--blue-dark); transform: translateY(-1px); }
    .btn-secondary { background: #eff4ff; color: #163167; }
    .btn-secondary:hover { background: #e3ecff; transform: translateY(-1px); }
    .btn-teal { background: var(--teal); color: white; }
    .btn-teal:hover { background: var(--teal-dark); }

    .hero-visual {
      background: linear-gradient(160deg, #ffffff, #e9f1ff);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      padding: 1.2rem;
    }

    .mock-card {
      background: white;
      border-radius: 14px;
      padding: 0.9rem;
      border: 1px solid #e8efff;
      display: flex;
      gap: 0.9rem;
      align-items: center;
      margin-bottom: 0.8rem;
    }

    .avatar {
      width: 54px;
      height: 54px;
      border-radius: 50%;
      background: linear-gradient(140deg, #7fb4ff, #c7ddff);
      flex: 0 0 auto;
    }

    .mock-lines { flex: 1; }
    .mock-lines span {
      display: block;
      height: 9px;
      border-radius: 99px;
      background: #e8f0ff;
      margin: 6px 0;
    }
    .mock-lines span:first-child { width: 65%; }
    .mock-lines span:nth-child(2) { width: 50%; }
    .mock-lines span:last-child { width: 38%; }

    .search-shell {
      margin-top: 1.6rem;
      background: white;
      border-radius: 18px;
      box-shadow: var(--shadow);
      border: 1px solid var(--border);
      padding: 0.9rem;
    }

    .search-form {
      display: grid;
      grid-template-columns: 2fr 1.2fr 1.2fr auto;
      gap: 0.7rem;
      align-items: center;
      position: relative;
    }

    .field {
      display: flex;
      align-items: center;
      gap: .55rem;
      border: 1px solid #d9e5ff;
      background: #fbfdff;
      border-radius: 12px;
      padding: 0.68rem .8rem;
    }

    .field svg { color: #5f76aa; flex: 0 0 auto; }
    .field input, .field select {
      border: none;
      outline: none;
      width: 100%;
      font-size: 1rem;
      background: transparent;
      color: #112246;
      font-family: inherit;
    }

    .detect-btn {
      border: none;
      background: #eef4ff;
      color: #1d4bb8;
      font-weight: 600;
      border-radius: 8px;
      padding: .45rem .6rem;
      cursor: pointer;
      flex: 0 0 auto;
    }

    .autocomplete {
      position: absolute;
      left: 0;
      top: calc(100% + 8px);
      width: min(520px, 100%);
      background: white;
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: var(--shadow);
      overflow: hidden;
      display: none;
      z-index: 25;
    }

    .autocomplete.open { display: block; }
    .autocomplete button {
      width: 100%;
      text-align: left;
      border: none;
      background: white;
      padding: 0.8rem 0.95rem;
      cursor: pointer;
      color: #20345d;
      font-family: inherit;
      font-size: .98rem;
    }
    .autocomplete button:hover,
    .autocomplete button.active {
      background: #f2f6ff;
      color: #1343aa;
    }

    section { padding: 4rem 0; }
    .section-title {
      font-size: clamp(1.55rem, 2.8vw, 2.2rem);
      margin: 0 0 .7rem;
      line-height: 1.15;
      color: #12224a;
    }
    .section-copy { margin: 0 0 2rem; color: var(--muted); font-size: 1.03rem; }

    .specialty-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .specialty-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: white;
      padding: 1rem;
      box-shadow: 0 6px 20px rgba(15, 54, 120, 0.06);
      transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
      display: block;
    }
    .specialty-card:hover {
      transform: translateY(-4px);
      border-color: #b7ceff;
      box-shadow: 0 12px 24px rgba(15, 54, 120, 0.13);
    }

    .icon-wrap {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      color: white;
      margin-bottom: .75rem;
      background: linear-gradient(135deg, var(--blue), #66a3ff);
    }
    .specialty-card h3 { margin: .2rem 0 .4rem; font-size: 1.1rem; }
    .specialty-card p { margin: 0; color: var(--muted); font-size: 0.95rem; }

    .stats {
      background: var(--surface);
      border-top: 1px solid #e6efff;
      border-bottom: 1px solid #e6efff;
    }

    .stats-row {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }

    .stat {
      background: white;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 1rem;
      text-align: center;
    }
    .stat strong { display: block; color: var(--blue); font-size: 1.55rem; line-height: 1.1; }
    .stat span { color: #4a5f85; font-weight: 500; }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }
    .step {
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 1.1rem;
      background: #fcfdff;
    }
    .step-index {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: #eaf1ff;
      color: #1b4ab6;
      font-weight: 800;
      margin-bottom: .7rem;
    }
    .step h3 { margin: 0 0 .45rem; }
    .step p { margin: 0; color: var(--muted); }

    .testimonials { background: var(--surface-2); }
    .quote-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }
    blockquote {
      margin: 0;
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 1.1rem;
      box-shadow: 0 4px 16px rgba(15,54,120,0.07);
    }
    blockquote p { margin: 0 0 1rem; color: #2a3e66; }
    blockquote footer { color: #4f6288; font-weight: 600; }

    .app-promo {
      background: linear-gradient(130deg, #0f4fe0, #1975ff);
      color: white;
    }
    .app-row {
      display: grid;
      grid-template-columns: 1.2fr .8fr;
      gap: 1rem;
      align-items: center;
    }
    .app-promo .section-title,
    .app-promo .section-copy { color: white; }
    .feature-list {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: .6rem;
      margin-bottom: 1.2rem;
      padding: 0;
      list-style: none;
    }
    .feature-list li {
      background: rgba(255,255,255,.14);
      border: 1px solid rgba(255,255,255,.2);
      border-radius: 10px;
      padding: .6rem .75rem;
      font-weight: 500;
    }

    .store-buttons { display: flex; gap: .7rem; flex-wrap: wrap; }
    .store {
      background: #ffffff;
      color: #103061;
      border-radius: 10px;
      padding: .75rem .95rem;
      font-weight: 700;
      font-size: .92rem;
    }

    .phone {
      margin-inline: auto;
      width: min(270px, 100%);
      background: #ffffff;
      border-radius: 28px;
      padding: 0.9rem;
      box-shadow: 0 16px 36px rgba(0, 0, 0, .22);
    }
    .screen {
      border-radius: 20px;
      background: linear-gradient(170deg, #e8f1ff, #f9fbff);
      padding: .9rem;
      min-height: 320px;
      border: 1px solid #dce8ff;
    }

    .site-footer {
      background: #0f1d3d;
      color: #d8e1fb;
      padding: 3rem 0 1.3rem;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1.2rem;
      margin-bottom: 1.3rem;
    }
    .footer-col h4 { color: #ffffff; margin: 0 0 .7rem; font-size: 1rem; }
    .footer-col a {
      display: block;
      color: #c7d4fa;
      margin: .45rem 0;
      font-size: .94rem;
    }
    .footer-col a:hover { color: #ffffff; }
    .copyright {
      border-top: 1px solid rgba(196, 214, 255, 0.2);
      padding-top: 1rem;
      color: #c7d4fa;
      font-size: .9rem;
    }

    @media (max-width: 1000px) {
      .hero-content, .app-row { grid-template-columns: 1fr; }
      .specialty-grid, .quote-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .steps { grid-template-columns: 1fr; }
      .search-form { grid-template-columns: 1fr; }
      .autocomplete { width: 100%; }
      .stats-row { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 760px) {
      .nav-links { display: none; }
      .menu-btn { display: inline-flex; }
      .hero { padding-top: 3.2rem; }
      .specialty-grid, .quote-grid, .feature-list, .footer-grid { grid-template-columns: 1fr; }
      .stat strong { font-size: 1.35rem; }
      .section-copy, .subtitle { font-size: 1rem; }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="logo" href="index.html" aria-label="MedBook Home">
        <span class="logo-mark" aria-hidden="true"></span>
        MedBook
      </a>

      <nav class="nav-links" aria-label="Primary">
        <a href="#specialties">Browse</a>
        <a href="#footer">Help</a>
        <a href="#">Log In</a>
        <a href="#" class="signup">Sign Up</a>
      </nav>

      <button class="menu-btn" id="menuToggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobileDrawer">
        <span aria-hidden="true"></span>
      </button>
    </div>
  </header>

  <aside class="mobile-drawer" id="mobileDrawer" aria-label="Mobile menu">
    <a href="#specialties">Browse</a>
    <a href="#">Log In</a>
    <a href="#">Sign Up</a>
  </aside>

  <main>
    <section class="hero" id="home">
      <div class="container hero-content">
        <div>
          <h1>Find and book the care you need</h1>
          <p class="subtitle">Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" type="button" onclick="document.getElementById('specialtyInput').focus()">Find a Doctor</button>
            <button class="btn btn-secondary" type="button" onclick="document.getElementById('searchForm').scrollIntoView({behavior:'smooth', block:'center'})">Search</button>
          </div>
        </div>

        <div class="hero-visual" aria-hidden="true">
          <div class="mock-card">
            <div class="avatar"></div>
            <div class="mock-lines"><span></span><span></span><span></span></div>
          </div>
          <div class="mock-card">
            <div class="avatar"></div>
            <div class="mock-lines"><span></span><span></span><span></span></div>
          </div>
          <div class="mock-card">
            <div class="avatar"></div>
            <div class="mock-lines"><span></span><span></span><span></span></div>
          </div>
        </div>
      </div>

      <div class="container search-shell" id="search">
        <form id="searchForm" class="search-form" action="search-results.html" method="get">
          <div class="field">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M11 4a7 7 0 1 1 0 14 7 7 0 0 1 0-14Zm10 16-4.4-4.4" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
            <input id="specialtyInput" name="q" type="text" autocomplete="off" placeholder="Search by condition, specialty, or doctor name" aria-label="Specialty, condition, or doctor" />
          </div>

          <div class="field">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 21s7-5.2 7-11A7 7 0 1 0 5 10c0 5.8 7 11 7 11Zm0-8a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z" stroke="currentColor" stroke-width="2"/></svg>
            <input id="locationInput" name="location" type="text" placeholder="City, state, or zip code" aria-label="Location" />
            <button class="detect-btn" type="button" id="detectLocation">Use my location</button>
          </div>

          <div class="field">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
            <select id="insuranceInput" name="insurance" aria-label="Insurance plan">
              <option value="">Choose your insurance plan</option>
              <option>Aetna</option>
              <option>Blue Cross</option>
              <option>Cigna</option>
              <option>UnitedHealthcare</option>
              <option>Kaiser Permanente</option>
              <option>Humana</option>
            </select>
          </div>

          <button class="btn btn-teal" type="submit">Search</button>

          <div class="autocomplete" id="autocomplete" role="listbox" aria-label="Search suggestions"></div>
        </form>
      </div>
    </section>

    <section id="specialties">
      <div class="container">
        <h2 class="section-title">Popular specialties</h2>
        <p class="section-copy">Browse trusted providers by specialty and book in just a few taps.</p>

        <div class="specialty-grid">
          <a class="specialty-card" href="search-results.html?specialty=Primary%20Care">
            <div class="icon-wrap">🩺</div>
            <h3>Primary Care</h3>
            <p>Annual checkups, sick visits, and preventive care</p>
          </a>
          <a class="specialty-card" href="search-results.html?specialty=Dentist">
            <div class="icon-wrap">🦷</div>
            <h3>Dentist</h3>
            <p>Cleanings, fillings, and oral health exams</p>
          </a>
          <a class="specialty-card" href="search-results.html?specialty=Dermatologist">
            <div class="icon-wrap">🧴</div>
            <h3>Dermatologist</h3>
            <p>Skin conditions, acne, and cosmetic consultations</p>
          </a>
          <a class="specialty-card" href="search-results.html?specialty=Psychiatrist">
            <div class="icon-wrap">🧠</div>
            <h3>Psychiatrist</h3>
            <p>Mental health evaluations and medication management</p>
          </a>
          <a class="specialty-card" href="search-results.html?specialty=Eye%20Doctor">
            <div class="icon-wrap">👓</div>
            <h3>Eye Doctor</h3>
            <p>Vision exams, glasses prescriptions, and eye health</p>
          </a>
          <a class="specialty-card" href="search-results.html?specialty=Orthopedic%20Surgeon">
            <div class="icon-wrap">🦴</div>
            <h3>Orthopedic Surgeon</h3>
            <p>Joint pain, fractures, and sports injuries</p>
          </a>
        </div>
      </div>
    </section>

    <section class="stats" aria-label="Platform statistics">
      <div class="container stats-row">
        <div class="stat"><strong>4.8M+</strong><span>verified patient reviews</span></div>
        <div class="stat"><strong>12,000+</strong><span>healthcare providers nationwide</span></div>
        <div class="stat"><strong>Same-day</strong><span>appointments available daily</span></div>
        <div class="stat"><strong>100% free</strong><span>for patients — always</span></div>
      </div>
    </section>

    <section id="how-it-works">
      <div class="container">
        <h2 class="section-title">How MedBook works</h2>
        <p class="section-copy">A faster, clearer way to find care when you need it.</p>

        <div class="steps">
          <article class="step">
            <div class="step-index">1</div>
            <h3>Search for a provider</h3>
            <p>Enter your specialty, condition, or doctor name with your location and insurance to browse profiles with credentials and office hours.</p>
          </article>
          <article class="step">
            <div class="step-index">2</div>
            <h3>Choose a time that works for you</h3>
            <p>View real-time availability and select an appointment slot that fits your schedule, including same-day and next-day options.</p>
          </article>
          <article class="step">
            <div class="step-index">3</div>
            <h3>Book your appointment instantly</h3>
            <p>Confirm your visit in a few clicks and receive instant confirmation with reminders so you never miss a visit.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="testimonials" id="testimonials">
      <div class="container">
        <h2 class="section-title">Patients trust MedBook</h2>
        <p class="section-copy">Verified stories from people who booked care quickly.</p>

        <div class="quote-grid">
          <blockquote>
            <p>“I found a great dermatologist near my office and booked a same-day appointment during my lunch break. MedBook made it incredibly easy.”</p>
            <footer>— Priya M., New York, NY</footer>
          </blockquote>
          <blockquote>
            <p>“As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes. Highly recommend!”</p>
            <footer>— James T., Chicago, IL</footer>
