  <script>
    const suggestions = [
      'Dentist', 'Back pain', 'Dr. Sarah Chen', 'Primary Care',
      'Dermatologist', 'Psychiatrist', 'Eye Doctor', 'Orthopedic Surgeon',
      'Pediatrician', 'Anxiety', 'Cardiologist', 'Migraine'
    ];

    const specialtyInput = document.getElementById('specialtyInput');
    const autocomplete = document.getElementById('autocomplete');
    let activeIndex = -1;

    function renderSuggestions(items) {
      autocomplete.innerHTML = '';
      if (!items.length) {
        autocomplete.classList.remove('open');
        return;
      }

      items.forEach((item, index) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.role = 'option';
        button.textContent = item;
        button.addEventListener('mousedown', (event) => {
          event.preventDefault();
          specialtyInput.value = item;
          autocomplete.classList.remove('open');
        });
        if (index === activeIndex) button.classList.add('active');
        autocomplete.appendChild(button);
      });

      autocomplete.classList.add('open');
    }

    specialtyInput.addEventListener('input', () => {
      const value = specialtyInput.value.trim().toLowerCase();
      activeIndex = -1;
      if (!value) {
        renderSuggestions(suggestions.slice(0, 6));
        return;
      }

      const filtered = suggestions.filter((item) => item.toLowerCase().includes(value)).slice(0, 8);
      renderSuggestions(filtered);
    });

    specialtyInput.addEventListener('focus', () => {
      const value = specialtyInput.value.trim().toLowerCase();
      const filtered = value
        ? suggestions.filter((item) => item.toLowerCase().includes(value)).slice(0, 8)
        : suggestions.slice(0, 6);
      renderSuggestions(filtered);
    });

    specialtyInput.addEventListener('keydown', (event) => {
      const options = autocomplete.querySelectorAll('button');
      if (!options.length) return;

      if (event.key === 'ArrowDown') {
        event.preventDefault();
        activeIndex = (activeIndex + 1) % options.length;
        renderSuggestions(Array.from(options).map((button) => button.textContent));
      } else if (event.key === 'ArrowUp') {
        event.preventDefault();
        activeIndex = (activeIndex - 1 + options.length) % options.length;
        renderSuggestions(Array.from(options).map((button) => button.textContent));
      } else if (event.key === 'Enter' && activeIndex >= 0) {
        event.preventDefault();
        specialtyInput.value = options[activeIndex].textContent;
        autocomplete.classList.remove('open');
      } else if (event.key === 'Escape') {
        autocomplete.classList.remove('open');
      }
    });

    document.addEventListener('click', (event) => {
      if (!autocomplete.contains(event.target) && event.target !== specialtyInput) {
        autocomplete.classList.remove('open');
      }
    });

    document.getElementById('detectLocation').addEventListener('click', () => {
      const locationInput = document.getElementById('locationInput');
      locationInput.value = 'Current location';
      locationInput.focus();
    });

    document.getElementById('searchForm').addEventListener('submit', (event) => {
      event.preventDefault();
      const params = new URLSearchParams(new FormData(event.target));
      window.location.href = `search-results.html?${params.toString()}`;
    });

    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');

    menuToggle.addEventListener('click', () => {
      const isOpen = mobileDrawer.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(isOpen));
      menuToggle.setAttribute('aria-label', isOpen ? 'Close menu' : 'Open menu');
    });

    document.addEventListener('click', (event) => {
      const clickedInside = mobileDrawer.contains(event.target) || menuToggle.contains(event.target);
      if (!clickedInside && mobileDrawer.classList.contains('open')) {
        mobileDrawer.classList.remove('open');
        menuToggle.setAttribute('aria-expanded', 'false');
        menuToggle.setAttribute('aria-label', 'Open menu');
      }
    });
  </script>
